// Helper functions
export const getAllDays = () => {
  return Object.keys(HUNDRED_DAYS_DSA)
    .sort((a, b) => {
      const dayA = parseInt(a.replace("day", ""));
      const dayB = parseInt(b.replace("day", ""));
      return dayA - dayB;
    })
    .map(key => HUNDRED_DAYS_DSA[key]);
};

export const getDayByNumber = (dayNumber) => {
  const day = HUNDRED_DAYS_DSA[`day${dayNumber}`];
  if (!day) {
    console.warn(`Day ${dayNumber} not found. Total days available: ${Object.keys(HUNDRED_DAYS_DSA).length}`);
    return null;
  }
  return day;
};

export const searchQuestions = (query, allDays) => {
  try {
    const lowerQuery = query.toLowerCase();
    const results = [];
    
    allDays.forEach(day => {
      if (day.questions) {
        day.questions.forEach(question => {
          if (
            question.title.toLowerCase().includes(lowerQuery) ||
            question.description.toLowerCase().includes(lowerQuery) ||
            question.topic.toLowerCase().includes(lowerQuery)
          ) {
            results.push({
              ...question,
              day: day.day
            });
          }
        });
      }
    });
    
    return results;
  } catch (error) {
    console.error("Error in searchQuestions:", error);
    return [];
  }
};

export const getQuestionsByTopic = (topic, allDays) => {
  try {
    const results = [];
    
    allDays.forEach(day => {
      if (day.questions) {
        day.questions.forEach(question => {
          if (question.topic.toLowerCase().includes(topic.toLowerCase())) {
            results.push({
              ...question,
              day: day.day
            });
          }
        });
      }
    });
    
    return results;
  } catch (error) {
    console.error("Error in getQuestionsByTopic:", error);
    return [];
  }
};

export const getQuestionsByDifficulty = (difficulty, allDays) => {
  try {
    const results = [];
    
    allDays.forEach(day => {
      if (day.questions) {
        day.questions.forEach(question => {
          if (question.difficulty.toLowerCase() === difficulty.toLowerCase()) {
            results.push({
              ...question,
              day: day.day
            });
          }
        });
      }
    });
    
    return results;
  } catch (error) {
    console.error("Error in getQuestionsByDifficulty:", error);
    return [];
  }
};
